import { readFileSync } from 'node:fs'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import dts from 'vite-plugin-dts'

// Icon entry points are generated by scripts/gen-icons.mjs (runs before every build).
const iconEntries: string[] = JSON.parse(readFileSync('src/icons/entries.json', 'utf8'))

export default defineConfig({
  plugins: [
    tailwindcss(),
    react(),
    dts({ include: ['src'], exclude: ['src/**/*.stories.tsx', 'src/main.tsx'], tsconfigPath: './tsconfig.build.json' }),
  ],
  build: {
    lib: {
      entry: {
        index: 'src/index.ts',
        ...Object.fromEntries(iconEntries.map((name) => [`icons/${name}`, `src/icons/${name}.ts`])),
      },
      formats: ['es', 'cjs'],
      fileName: (format, entryName) => `${entryName}.${format === 'es' ? 'js' : 'cjs'}`,
      cssFileName: 'index',
    },
    rollupOptions: {
      // Icon libraries stay external so consumers' bundlers tree-shake them per icon.
      external: [
        'react',
        'react-dom',
        'react/jsx-runtime',
        'lucide-react',
        '@lucide/lab',
        /^react-icons(\/.*)?$/,
      ],
    },
    cssCodeSplit: false,
  },
})
